<script setup lang="ts">
import {computed} from 'vue';
import type {StudyroomRun} from '../../../shared/types/outline';
import type {StudyroomStep} from '../../../shared/types/studyroom';
import {classroomPages} from '../../classroom-pages';
import {userApi} from '../../runtime';
const props=defineProps<{run:StudyroomRun;steps:StudyroomStep[];activeId:string;pageId:string}>();
defineEmits<{select:[unitId:string,fragmentId?:string,pageId?:string];close:[]}>();
const groups=computed(()=>props.run.knowledgePoints.map(point=>({...point,pages:point.fragments.flatMap((fragment,index)=>{const step=props.steps.find(step=>step.id===fragment.stepId);if(!step)return [];const pages=classroomPages(step,fragment.contentRevision);return [...pages.map(page=>({...page,fragmentId:fragment.id})),...(index===point.fragments.length-1&&point.fragments.every(fragment=>fragment.stepId)?[{id:`${step.id}:${fragment.contentRevision}:quiz`,title:'小测',kind:'QUIZ',fragmentId:fragment.id,resourceId:undefined}]:[])];})})));
</script>
<template><nav class="page-directory" aria-label="课程页面目录"><section v-for="(group,index) in groups" :key="group.id"><button class="point-heading" type="button" :data-unit-id="group.id" :aria-current="group.id===activeId?'step':undefined" @click="$emit('select',group.id)"><span>{{String(index+1).padStart(2,'0')}}</span><strong>{{group.title}}</strong></button><button v-for="(page,pageIndex) in group.pages" :key="page.id" type="button" class="page-thumbnail" :aria-current="page.id===pageId?'page':undefined" @click="$emit('select',group.id,page.fragmentId,page.id)"><div class="thumbnail-label"><span>{{pageIndex+1}}</span>{{page.title}}</div><div class="thumbnail-preview"><img v-if="page.kind==='PPT'&&page.resourceId" :src="userApi.coursewareImageUrl(page.resourceId)" alt="" loading="lazy"><template v-else><strong>{{page.title}}</strong><span class="thumbnail-rule"/><span class="thumbnail-rule short"/><span v-if="page.kind==='QUIZ'" class="thumbnail-quiz">○　○　○　○</span></template></div></button><p v-if="!group.pages.length" class="point-status">{{group.status==='NEEDS_ATTENTION'?'内容需要重新准备':'内容正在准备中'}}</p></section></nav></template>
<style scoped>
.page-directory{display:flex;flex-direction:column;gap:26px;padding:10px 10px 22px;min-width:0}.page-directory button{font:inherit;color:var(--text);border:1px solid transparent;background:transparent;cursor:pointer;transition:background 160ms ease,border-color 160ms ease,transform 160ms ease}.point-heading{display:flex;gap:8px;text-align:left;padding:4px 7px 10px;width:100%;font-size:13px;line-height:1.6}.point-heading>span{font:11px var(--font-mono);color:var(--text-muted);padding-top:4px;flex-shrink:0}.point-heading strong{font-weight:550}.point-status{font-size:12px;line-height:1.7;color:var(--text-muted);margin:6px 7px}.page-thumbnail{display:block;width:100%;padding:8px;border-radius:10px;text-align:left;margin-top:4px}.page-thumbnail:hover{background:var(--surface-subtle)}.page-thumbnail[aria-current]{border-color:var(--line);background:var(--surface-subtle)}.thumbnail-label{display:flex;gap:7px;font-size:11px;line-height:1.6;margin-bottom:6px}.thumbnail-label>span{color:var(--text-muted)}.thumbnail-preview{aspect-ratio:16/9;border:1px solid var(--line);border-radius:6px;background:var(--surface);overflow:hidden;padding:13px;display:flex;flex-direction:column;justify-content:center;gap:8px}.thumbnail-preview:has(img){padding:0}.thumbnail-preview img{width:100%;height:100%;object-fit:contain}.thumbnail-preview strong{font-size:11px;line-height:1.5;font-weight:550}.thumbnail-rule{height:3px;border-radius:3px;background:var(--line);width:90%}.thumbnail-rule.short{width:60%}.thumbnail-quiz{font-size:11px;color:var(--text-muted)}button:focus-visible{outline:2px solid var(--text);outline-offset:2px}button:active{transform:scale(.98)}@media(prefers-reduced-motion:reduce){button{transition:none}button:active{transform:none}}
</style>
